const $=id=>document.getElementById(id);const money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0});const dateFmt=new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC'});let allSales=[];
const filterIds=['modelFilter','yearFilter','stateFilter','paymentFilter','statusFilter'];
function unique(field){return [...new Set(allSales.map(x=>x[field]).filter(v=>v!==null&&v!==''))].sort((a,b)=>String(a).localeCompare(String(b),'pt-BR',{numeric:true}))}
function fillSelect(id,field){const select=$(id);unique(field).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;select.appendChild(o)})}
function filtered(){const map={modelFilter:'model',yearFilter:'year',stateFilter:'state',paymentFilter:'payment',statusFilter:'status'};return allSales.filter(row=>filterIds.every(id=>!$(id).value||String(row[map[id]])===$(id).value))}
function groupSum(rows,key){return rows.reduce((a,r)=>{const k=key(r);if(k)a[k]=(a[k]||0)+(Number(r.price)||0);return a},{})}
function groupCount(rows,key){return rows.reduce((a,r)=>{const k=key(r)||'Não informado';a[k]=(a[k]||0)+1;return a},{})}
function setupCanvas(canvas){const dpr=window.devicePixelRatio||1,rect=canvas.getBoundingClientRect();canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);return{c,w:rect.width,h:rect.height}}
function noData(c,w,h){c.fillStyle='#888';c.textAlign='center';c.font='14px Arial';c.fillText('Sem dados para exibir',w/2,h/2)}
function lineChart(rows){const {c,w,h}=setupCanvas($('monthlyChart'));const grouped=groupSum(rows,r=>r.date&&r.date.slice(0,7));const entries=Object.entries(grouped).sort();if(!entries.length)return noData(c,w,h);const pad={l:55,r:20,t:20,b:38},max=Math.max(...entries.map(x=>x[1]),1);c.strokeStyle='#333';c.fillStyle='#8e8e8e';c.font='11px Arial';c.textAlign='right';for(let i=0;i<=4;i++){const y=pad.t+(h-pad.t-pad.b)*i/4;c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.fillText('$'+Math.round(max*(4-i)/4/1000)+'k',pad.l-8,y+4)}const pts=entries.map(([k,v],i)=>({x:pad.l+(w-pad.l-pad.r)*(entries.length===1?.5:i/(entries.length-1)),y:pad.t+(h-pad.t-pad.b)*(1-v/max),k,v}));c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.strokeStyle='#c8a45a';c.lineWidth=3;c.stroke();c.lineTo(pts.at(-1).x,h-pad.b);c.lineTo(pts[0].x,h-pad.b);c.closePath();const grad=c.createLinearGradient(0,pad.t,0,h-pad.b);grad.addColorStop(0,'rgba(200,164,90,.28)');grad.addColorStop(1,'rgba(200,164,90,0)');c.fillStyle=grad;c.fill();pts.forEach((p,i)=>{c.fillStyle='#c8a45a';c.beginPath();c.arc(p.x,p.y,4,0,Math.PI*2);c.fill();c.fillStyle='#aaa';c.textAlign='center';c.fillText(p.k,i===0?p.x+10:i===pts.length-1?p.x-10:p.x,h-14)})}
function barChart(rows){const {c,w,h}=setupCanvas($('modelChart'));const entries=Object.entries(groupSum(rows,r=>r.model)).sort((a,b)=>b[1]-a[1]).slice(0,6);if(!entries.length)return noData(c,w,h);const max=entries[0][1],pad={l:120,r:32,t:10,b:14},gap=9,bh=(h-pad.t-pad.b-gap*(entries.length-1))/entries.length;c.font='11px Arial';entries.forEach(([name,value],i)=>{const y=pad.t+i*(bh+gap);c.fillStyle='#aaa';c.textAlign='right';c.fillText(name.length>17?name.slice(0,16)+'…':name,pad.l-10,y+bh/2+4);c.fillStyle='#292929';c.fillRect(pad.l,y,w-pad.l-pad.r,bh);c.fillStyle=i===0?'#d5001c':'#c8a45a';c.fillRect(pad.l,y,(w-pad.l-pad.r)*value/max,bh);c.fillStyle='#f4f1eb';c.textAlign='left';c.fillText('$'+Math.round(value/1000)+'k',pad.l+7,y+bh/2+4)})}
function donutChart(rows){const {c,w,h}=setupCanvas($('statusChart'));const entries=Object.entries(groupCount(rows,r=>r.status)).sort((a,b)=>b[1]-a[1]).slice(0,6);if(!entries.length)return noData(c,w,h);const colors=['#d5001c','#c8a45a','#e8e3da','#777','#3ecf8e','#66512c'],total=entries.reduce((s,x)=>s+x[1],0),cx=w*.34,cy=h*.48,r=Math.min(w,h)*.29;let start=-Math.PI/2;entries.forEach(([,v],i)=>{const end=start+Math.PI*2*v/total;c.beginPath();c.arc(cx,cy,r,start,end);c.arc(cx,cy,r*.58,end,start,true);c.closePath();c.fillStyle=colors[i];c.fill();start=end});c.fillStyle='#f6f4ef';c.textAlign='center';c.font='26px Georgia';c.fillText(total,cx,cy+5);c.fillStyle='#999';c.font='11px Arial';c.fillText('PEDIDOS',cx,cy+23);c.textAlign='left';entries.forEach(([name,v],i)=>{const y=36+i*31,x=w*.68;c.fillStyle=colors[i];c.fillRect(x,y-8,9,9);c.fillStyle='#bbb';c.font='11px Arial';c.fillText(name.length>18?name.slice(0,17)+'…':name,x+15,y);c.fillStyle='#fff';c.textAlign='right';c.fillText(v,w-8,y);c.textAlign='left'})}
function renderTable(rows){const body=$('salesTable');body.innerHTML='';rows.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,100).forEach(r=>{const tr=document.createElement('tr');const d=r.date?dateFmt.format(new Date(r.date+'T00:00:00Z')):'Data inválida';tr.innerHTML=`<td>${d}</td><td>${r.model}</td><td>${r.year??'—'}</td><td>${r.state}</td><td>${r.payment}</td><td><span class="status ${r.status==='Delivered'?'delivered':''}">${r.status}</span></td><td>${money.format(r.price||0)}</td>`;body.appendChild(tr)});$('tableCount').textContent=`${rows.length} registro${rows.length===1?'':'s'}`;$('emptyState').hidden=rows.length>0}
function update(){const rows=filtered(),revenue=rows.reduce((s,r)=>s+(Number(r.price)||0),0),delivered=rows.filter(r=>r.status==='Delivered').length;$('totalRevenue').textContent=money.format(revenue);$('totalSales').textContent=rows.length.toLocaleString('pt-BR');$('avgTicket').textContent=money.format(rows.length?revenue/rows.length:0);$('deliveryRate').textContent=(rows.length?delivered/rows.length*100:0).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';lineChart(rows);barChart(rows);donutChart(rows);renderTable(rows)}
async function init(){try{const res=await fetch('data/sales.json');if(!res.ok)throw new Error();allSales=await res.json();[['modelFilter','model'],['yearFilter','year'],['stateFilter','state'],['paymentFilter','payment'],['statusFilter','status']].forEach(x=>fillSelect(...x));filterIds.forEach(id=>$(id).addEventListener('change',update));$('resetFilters').addEventListener('click',()=>{filterIds.forEach(id=>$(id).value='');update()});window.addEventListener('resize',update);update()}catch(e){document.querySelector('main').innerHTML='<section class="panel empty">Não foi possível carregar os dados da dashboard.</section>'}}init();
